import React, { useMemo } from "react"
import dayjs from "dayjs"
import { MemoListItemDto } from "../../types/dto"
import { IconWrapper } from "../icons"
import { Hash } from "@phosphor-icons/react"

interface MemoCardProps {
  memo: MemoListItemDto
}

export const MemoCard: React.FC<MemoCardProps> = ({ memo }) => {
  // Convert markdown-like content to HTML
  const contentHtml = useMemo(() => {
    return (memo?.content || "")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
      .replace(/\*(.+?)\*/g, "<em>$1</em>")
      .replace(/`(.+?)`/g, '<code class="bg-background-secondary px-1 py-0 rounded-sm text-[13px] font-mono">$1</code>')
      .replace(/\n/g, "<br />")
  }, [memo?.content])

  // Format date with relative time
  const formattedDate = useMemo(() => {
    const date = dayjs(memo.createdAt)
    const now = dayjs()
    const diffDays = now.diff(date, "day")

    if (diffDays === 0) {
      return "今天 " + date.format("HH:mm")
    } else if (diffDays === 1) {
      return "昨天 " + date.format("HH:mm")
    } else if (diffDays < 7) {
      return diffDays + " 天前"
    } else if (diffDays < 30) {
      return Math.floor(diffDays / 7) + " 周前"
    } else {
      return date.format("YYYY-MM-DD")
    }
  }, [memo.createdAt])

  return (
    <article className="p-3.5 sm:p-4">
      {/* Header */}
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-1.5">
          {/* Date badge - 更小的字体 */}
          <div className="inline-flex items-center px-2 py-0.5 rounded-md bg-background-secondary text-[11px] text-foreground-muted">
            {formattedDate}
          </div>

          {/* Content type indicator */}
          {memo.type !== "text" && (
            <span className="text-[11px] text-foreground-muted">
              {memo.type === "audio" ? "🎵 音频" : "🎬 视频"}
            </span>
          )}
        </div>
      </div>

      {/* Content */}
      <div
        className="text-foreground text-[14px] leading-7 max-w-none"
        dangerouslySetInnerHTML={{ __html: contentHtml }}
      />

      {/* Tags - 无边框分隔 */}
      {memo?.tags && memo.tags.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mt-3 pt-2">
          {memo.tags?.map((tag) => (
            <span
              key={tag.tagId}
              className="inline-flex items-center gap-1 px-2.5 py-1 text-[11px] font-medium text-accent hover:text-accent-hover transition-colors cursor-pointer bg-accent-subtle rounded-md"
            >
              <IconWrapper icon={Hash} size={10} />
              {tag.name}
            </span>
          ))}
        </div>
      )}
    </article>
  )
}

export default MemoCard
